** https://genuary.art/
** Prompt of the day : Exactly 42 lines of code.
*/
#define sat(a) clamp(a, 0., 1.)
#define rot(a) mat2(cos(a), -sin(a), sin(a), cos(a))
#define POSITION (sin(iTime*.25))
#define EPS vec2(0.01,0.)
#define getNorm(p) (normalize(vec3(map(p+EPS.xxx))-vec3(map(p-EPS.xyy),map(p-EPS.yxy),map(p-EPS.yyx))));
float _seed;
float hash(float seed) { return fract(sin(seed*123.456)*123.456); }
float rand() { return hash(_seed++); }
float _cube(vec3 p, vec3 s) { vec3 l = abs(p)-s; return max(l.x, max(l.y, l.z)); }
float _cucube(vec3 p, vec3 s, vec3 th) {
    float c = max(_cube(p, s), -_cube(p.xyx, s.xyx-th.xyx));
    return max(max(c, -_cube(p.yzy, s.yzy-th.yzy)), -_cube(p.xzx, s.xyx-th.xzx));
}
float map(vec3 p) {
    vec3 op = p; p.xz *= rot(.75); p.yz *= rot(.75+iTime*.1);
    float c = _cube(p, vec3(1.));
    c -= texture(iChannel0, p*.1+vec3(-.5,-.3,.7)*iTime*.02).x*.2-texture(iChannel0, p*.1).x*.05
    -texture(iChannel0, p*.25).x*.05-texture(iChannel0, p*.45+iTime*.05).x*.02
    -texture(iChannel0, p*.55).x*.02-texture(iChannel0, p*.85).x*.01;
    c -= -texture(iChannel0, p*.15).x*.4*(1.-smoothstep(0.,1.,sat((abs(op.x-POSITION))*1.)));
    p.xy *= rot(.5); p.yz *= rot(.5);
    return min(c, _cucube(p, vec3(1.), vec3(.01)));
}
vec3 glow(vec3 p) {
    return mix(vec3(0.), vec3(0.961,0.337,0.153),
    (1.-smoothstep(0.,1.,sat((abs(p.x-POSITION))*1.)))*(1.-sat(length(p.zy)-.1)));
}
void mainImage( out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = ((fragCoord-.5*iResolution.xy)/iResolution.xx)*1.5; _seed = iTime + texture(iChannel0, uv.xyx).x;
    vec3 acc = vec3(0.), col = vec3(0.282,0.137,0.118)*(1.-sat(length(uv)*1.5)), ro = vec3(0.,0.,-5.), rd = normalize(vec3(uv, 1.)), p = ro;
    for (float i = 0., res = map(p); i < 100. && distance(p, ro) < 10.; ++i, res = map(p)) {
        if (res < EPS.x) {
            vec3 n = getNorm(p);
            vec3 refl = normalize(reflect(rd, n)+.7*normalize(vec3(rand(), rand(), rand())-.5));
            col = vec3(.15)*sat(dot(normalize(vec3(1.,5.,1.)), n))+glow(p)+texture(iChannel1, refl).xyz*.34;
            break;
        }
        acc += glow(p)*(1.-sat(res/.75))*.3;
        p += rd * res * .5;
    }
    fragColor = vec4(col+acc,1.0);
}
